import {cabinet,rect,text,line,colors,clamp} from './cabinet.js';
// A seeded phrase prevents impossible simultaneous lane chords; all notes are visible early.
export const rhythmPattern=[0,1,2,3,2,1,0,2,1,3,2,0,3,1,2,3,0,0,1,1,2,2,3,3,2,0,1,3,0,2,3,1];
export function rhythmJudgment(error){return Math.abs(error)<=.085?'perfect':Math.abs(error)<=.19?'good':null;}
export function createRhythm(mount,api){const q=cabinet(mount,api,{accent:'#88caff'}),c=q.c;let notes=[],clock=0,life=5,combo=0,best=0,flash=[0,0,0,0];
 function reset(){notes=Array.from({length:64},(_,i)=>({lane:rhythmPattern[i%32],time:i<32?2+i*.48:2+32*.48+(i-32)*.42,hit:false,miss:false,beat:false}));clock=0;life=5;combo=0;best=0;flash=[0,0,0,0];}
 function hit(lane){if(!q.active)return;flash[lane]=.18;const n=notes.find(n=>n.lane===lane&&!n.hit&&!n.miss&&Math.abs(n.time-clock)<=.19);if(!n){q.sound('empty');return;}const judgment=rhythmJudgment(n.time-clock);n.hit=true;combo++;best=Math.max(best,combo);q.add((judgment==='perfect'?100:60)+Math.min(combo,20)*2);q.sound(['one','two','three','four'][lane]);q.burst(45+lane*90,370,colors[lane],8);q.say(judgment==='perfect'?`PERFECT · ${combo} COMBO`:`GOOD · ${combo} COMBO`);}
 reset();return {start(){reset();q.start();},tap(p){p=q.local(p);if(p.y>35&&p.y<448)hit(clamp(Math.floor(p.x/90),0,3));},direction(d){hit({left:0,up:1,down:2,right:3}[d]);},action(){const n=notes.find(n=>!n.hit&&!n.miss);if(n)hit(n.lane);},tick(dt){q.frame(dt,dt=>{clock+=dt;flash=flash.map(v=>Math.max(0,v-dt));for(const n of notes){if(!n.beat&&clock>=n.time){n.beat=true;q.sound('beat');}if(!n.hit&&!n.miss&&clock>n.time+.19){n.miss=true;life--;combo=0;q.sound('miss');q.say('MISSED · catch the next beat');if(life<=0){q.finish('Find that rhythm.',`${q.score} points · best combo ${best}.`,false);return;}}}if(clock>notes.at(-1).time+.5)q.finish('Encore, please.',`64 beats · best combo ${best} · ${q.score} points.`,true);},()=>{q.header(`${'♥ '.repeat(Math.max(0,life)).trim()}`,`${combo} COMBO`);for(let lane=0;lane<4;lane++){rect(c,lane*90+4,42,82,391,flash[lane]>0?colors[lane]+'44':'#24334b',10);rect(c,lane*90+6,344,78,52,colors[lane]+'33',8);text(c,['←','↑','↓','→'][lane],45+lane*90,416,23,colors[lane],700);}line(c,8,370,352,370,'#e4f1ff',3);for(const n of notes){if(n.hit||n.miss)continue;const y=370-(n.time-clock)*200;if(y<45||y>426)continue;rect(c,n.lane*90+12,y-14,66,28,colors[n.lane],7);rect(c,n.lane*90+20,y-9,50,3,'#ffffff66',2);}if(clock<1.4){text(c,'GET INTO THE GROOVE',180,185,18,'#d4e8ff',750);text(c,'Tap a lane when its tile hits the line.',180,216,14,'#b4cbe1');}q.footer('Tap each lane on the white line.');});},destroy:q.destroy};}
